-		byPath[candidate] = append(byPath[candidate], evidence)
-	}
-
-	remaining := int64(affectedMaxTotalBytes)
-	skippedContent := 0
-	for _, candidate := range paths {
-		if candidate == "" {
-			continue
-		}
-		candidate = path.Clean(candidate)
-		if changed[candidate] {
-			continue
-		}
-		for _, changedPath := range changedPaths {
